// ── UTILITY FUNCTIONS ──────────────────────────────────────
function generateId(prefix = 'id') {
  return prefix + '_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

function getCurrentMonth() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

function getMonthLabel(monthStr) {
  if (!monthStr) return '';
  const [y, m] = monthStr.split('-').map(Number);
  return new Date(y, m - 1, 1).toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
}

function formatDate(d) {
  if (!d) return '';
  const date = d instanceof Date ? d : new Date(d);
  return date.toISOString().split('T')[0];
}

function formatDateDisplay(d) {
  if (!d) return '';
  const date = new Date(d + 'T00:00:00');
  return date.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' });
}

function formatCurrency(amount, currency = '₹') {
  return `${currency}${Number(amount || 0).toLocaleString('en-IN')}`;
}

async function hashPin(pin) {
  try {
    if (typeof crypto !== 'undefined' && crypto.subtle && typeof crypto.subtle.digest === 'function') {
      const buf = new TextEncoder().encode(pin);
      const hash = await crypto.subtle.digest('SHA-256', buf);
      return Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, '0')).join('');
    }
  } catch (e) {}
  // Fallback hash implementation for offline/file:// or legacy browsers
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < pin.length; i++) {
    const ch = pin.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return 'fb_' + (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}

function getInitials(name) {
  if (!name) return '?';
  return name.split(' ').map(w => w[0]).join('').toUpperCase().slice(0, 2);
}

function getAvatarColor(name) {
  const colors = [
    'linear-gradient(135deg,#0EA5E9,#8B5CF6)',
    'linear-gradient(135deg,#22C55E,#0EA5E9)',
    'linear-gradient(135deg,#F59E0B,#EF4444)',
    'linear-gradient(135deg,#8B5CF6,#EC4899)',
    'linear-gradient(135deg,#14B8A6,#0EA5E9)',
    'linear-gradient(135deg,#F97316,#F59E0B)',
  ];
  let hash = 0;
  for (const c of (name || '')) hash = (hash * 31 + c.charCodeAt(0)) & 0xFFFFFF;
  return colors[Math.abs(hash) % colors.length];
}

function getMonthOffset(monthStr, offset) {
  const [y, m] = monthStr.split('-').map(Number);
  const d = new Date(y, m - 1 + offset, 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

function getLast12Months() {
  const months = [];
  for (let i = 11; i >= 0; i--) {
    months.push(getMonthOffset(getCurrentMonth(), -i));
  }
  return months;
}

function getMonthsRange(count) {
  const months = [];
  for (let i = count - 1; i >= 0; i--) {
    months.push(getMonthOffset(getCurrentMonth(), -i));
  }
  return months;
}

function getMonthsBetween(startMonth, endMonth) {
  if (!startMonth || !endMonth) return getLast12Months();
  if (startMonth > endMonth) {
    const tmp = startMonth;
    startMonth = endMonth;
    endMonth = tmp;
  }
  const [startY, startM] = startMonth.split('-').map(Number);
  const [endY, endM] = endMonth.split('-').map(Number);
  
  const months = [];
  let currY = startY;
  let currM = startM;
  
  while (currY < endY || (currY === endY && currM <= endM)) {
    months.push(`${currY}-${String(currM).padStart(2, '0')}`);
    currM++;
    if (currM > 12) {
      currM = 1;
      currY++;
    }
    // safety limit 120 months (10 years)
    if (months.length > 120) break;
  }
  return months.length > 0 ? months : [startMonth];
}

function getEarliestDataMonth() {
  const dates = [];
  try {
    const tenants = DB.getTenants() || [];
    tenants.forEach(t => {
      if (t.joiningDate) dates.push(t.joiningDate.slice(0, 7));
      if (t.createdAt) dates.push(t.createdAt.slice(0, 7));
    });
    const payments = DB.getPayments() || [];
    payments.forEach(p => {
      if (p.month) dates.push(p.month);
      if (p.date) dates.push(p.date.slice(0, 7));
    });
    const expenses = DB.getAllExpenses ? DB.getAllExpenses() : (DB._arr(DB.KEYS.EXPENSES) || []);
    expenses.forEach(e => {
      if (e.month) dates.push(e.month);
      if (e.date) dates.push(e.date.slice(0, 7));
    });
  } catch (e) {
    console.warn('Error finding earliest data month:', e);
  }
  const valid = dates.filter(d => /^\d{4}-\d{2}$/.test(d)).sort();
  if (valid.length > 0) return valid[0];
  return getMonthOffset(getCurrentMonth(), -11);
}

function getLatestDataMonth() {
  const dates = [];
  try {
    const payments = DB.getPayments() || [];
    payments.forEach(p => {
      if (p.month) dates.push(p.month);
      if (p.date) dates.push(p.date.slice(0, 7));
    });
    const expenses = DB.getAllExpenses ? DB.getAllExpenses() : (DB._arr(DB.KEYS.EXPENSES) || []);
    expenses.forEach(e => {
      if (e.month) dates.push(e.month);
      if (e.date) dates.push(e.date.slice(0, 7));
    });
  } catch (e) {
    console.warn('Error finding latest data month:', e);
  }
  const valid = dates.filter(d => /^\d{4}-\d{2}$/.test(d)).sort();
  if (valid.length > 0) return valid[valid.length - 1];
  return getCurrentMonth();
}
